import{_ as s,o as e,c as i,a2 as a}from"./chunks/framework.Wk4ah3nE.js";const u=JSON.parse('{"title":"Proxmox VM Autoscale","titleTemplate":"Right-size Proxmox VMs automatically","description":"Threshold-based CPU and RAM autoscaling for Proxmox VE virtual machines — a systemd service that drives qm over SSH, with hotplug support, host safety limits and Gotify/SMTP notifications.","frontmatter":{"layout":"home","title":"Proxmox VM Autoscale","titleTemplate":"Right-size Proxmox VMs automatically","description":"Threshold-based CPU and RAM autoscaling for Proxmox VE virtual machines — a systemd service that drives qm over SSH, with hotplug support, host safety limits and Gotify/SMTP notifications.","hero":{"name":"Proxmox VM Autoscale","text":"Right-size your VMs while they run","tagline":"A small systemd service that watches CPU and RAM on your Proxmox VE guests and adjusts cores and memory through qm over SSH — with hotplug, host safety limits and notifications.","image":{"src":"/favicon.svg","alt":"Proxmox VM Autoscale"},"actions":[{"theme":"brand","text":"Get started","link":"/guide/"},{"theme":"alt","text":"Installation","link":"/guide/installation"},{"theme":"alt","text":"View on GitHub","link":"https://github.com/fabriziosalmi/proxmox-vm-autoscale"}]},"features":[{"icon":"📈","title":"Threshold-based scaling","details":"Scale cores and RAM up past a high-water mark and back down below a low one. One step per decision, bounded by limits you set, rate-limited by a per-resource cooldown.","link":"/guide/how-it-works","linkText":"How decisions are made"},{"icon":"⚡","title":"Live changes where possible","details":"With hotplug and NUMA enabled, vCPU and balloon memory changes apply to a running guest. Where they cannot, the service says so in the log instead of pretending.","link":"/guide/hotplug","linkText":"Hotplug and NUMA"},{"icon":"🛡️","title":"Host safety first","details":"Every scaling decision is gated on the host itself having headroom. If the node is above your CPU or RAM ceiling, nothing scales up on it.","link":"/guide/host-limits","linkText":"Host safety limits"},{"icon":"🔔","title":"Notifications that mean something","details":"Gotify push and SMTP email on real scaling actions and on errors — not on every poll. Both optional, both independent.","link":"/guide/notifications","linkText":"Configure notifications"},{"icon":"🧾","title":"Usage tracking for hosters","details":"Records every spec change with a timestamp and turns a period into a costed CSV report. Useful if you bill customers for what they actually consumed.","link":"/guide/billing","linkText":"Billing tracking"},{"icon":"🔐","title":"Root SSH, treated seriously","details":"The service holds credentials for root on your hypervisors. The security section documents exactly what that exposes and how to narrow it.","link":"/security/","linkText":"Threat model"}],"head":[["link",{"rel":"canonical","href":"https://fabriziosalmi.github.io/proxmox-vm-autoscale/"}],["meta",{"property":"og:url","content":"https://fabriziosalmi.github.io/proxmox-vm-autoscale/"}],["meta",{"property":"og:title","content":"Proxmox VM Autoscale"}],["meta",{"property":"og:description","content":"Threshold-based CPU and RAM autoscaling for Proxmox VE virtual machines — a systemd service that drives qm over SSH, with hotplug support, host safety limits and Gotify/SMTP notifications."}]]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":null}'),o={name:"index.md"};function n(l,t,r,h,d,c){return e(),i("div",null,[...t[0]||(t[0]=[a(`<h2 id="is-this-for-you" tabindex="-1">Is this for you? <a class="header-anchor" href="#is-this-for-you" aria-label="Permalink to &quot;Is this for you?&quot;">​</a></h2><p>This service suits a homelab or a small fleet where a handful of VMs have <strong>bursty, uncorrelated load</strong> and you would rather not over-provision all of them for the peak. It reads usage from the hypervisor, compares it against thresholds you set, and moves one step at a time.</p><p>It is deliberately not a cluster scheduler. It does not migrate guests, does not create or destroy VMs, and does not model future load — see <a href="/proxmox-vm-autoscale/guide/#what-it-does-not-do">what it does not do</a> before you build anything on top of it.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Install on a Proxmox node (or any Linux host with SSH access to one)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &lt;(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://raw.githubusercontent.com/fabriziosalmi/proxmox-vm-autoscale/main/install.sh)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Point it at your hosts and VMs, then start it</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nano</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/local/bin/vm_autoscale/config.yaml</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vm_autoscale.service</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">journalctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vm_autoscale.service</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">Read this before running it in production</p><p>The service authenticates to your Proxmox hosts as <strong>root</strong> and issues <code>qm set</code> against live guests. Read the <a href="/proxmox-vm-autoscale/security/">threat model</a> and the <a href="/proxmox-vm-autoscale/reference/limitations.html">known limitations</a> first. There is no dry-run mode.</p></div>`,5)])])}const m=s(o,[["render",n]]);export{u as __pageData,m as default};
